import {chatHTML,bindChat,initChat,clearChat} from './chat-ui.js';
import {initMovies,discoverHTML,dailyMovieHTML,bindMovies} from './movie-ui.js';
import {notificationCenter,activityCenter,analyzeNote} from './runtime-ui.js';
import {runtimeError,rows} from './services/runtime-service.js';
import {configured,errorMessage,getClient} from './supabase-client.js';
import {requireSession,watchSession,logout} from './auth-service.js';
import {adminService} from './services/admin-service.js';
import {renderAdmin,loadAdmin,bindAdmin} from './admin-ui.js';
import {storage,movies} from './data-service.js';
import {icon} from './icons.js';

let adminData={},adminArgs={},saving=false,sessionActive=false;
let data=storage.read(),query='',filter='Hamısı',list='Hamısı',busy=false;
const $=s=>document.querySelector(s),page=document.body.dataset.page,admin=document.body.dataset.admin==='true';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='',ic='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const ib=(text,action,ic)=>`<button type="button" class="icon-btn" aria-label="${text}" data-action="${action}">${icon(ic)}</button>`;
const months=['yanvar','fevral','mart','aprel','may','iyun','iyul','avqust','sentyabr','oktyabr','noyabr','dekabr'];
const weekdays=['bazar','bazar ertəsi','çərşənbə axşamı','çərşənbə','cümə axşamı','cümə','şənbə'];
const names={home:'Ana səhifə',notes:'Qeydlər',discover:'Kəşf et',ai:'AI Köməkçi',dashboard:'İcmal',users:'İstifadəçilər',models:'AI modelləri',jarvis:'JARVIS',movies:'Filmlər',settings:'Parametrlər'};
const routes={home:'index.html',notes:'notes.html',discover:'discover.html',ai:'ai.html',dashboard:'index.html',users:'users.html',models:'ai-management.html',jarvis:'jarvis.html',movies:'movies.html',settings:'settings.html'};
async function save(){saving=true;document.body.classList.add('saving');try{await storage.write(data);return true;}catch(error){if(accessFailure(error)){sessionActive=false;clearChat();storage.clear();data=storage.read();$('#modal').close();failureState(error);return false;}data=storage.read();if(error?.code==='40001'){try{data=await storage.load();}catch{}}render();toast(errorMessage(error));return false;}finally{saving=false;document.body.classList.remove('saving');}}
function toast(s){const t=document.createElement('div');t.className='toast';t.textContent=s;$('#toasts').append(t);setTimeout(()=>t.remove(),3500);}
function heading(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">${admin?'ASTRA / İDARƏETMƏ':'GÜNÜNÜ SADƏLƏŞDİR'}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function layout(){document.body.classList.toggle('admin',admin);const items=admin?['dashboard','users','models','jarvis','movies','settings']:['home','notes','discover','ai'];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="${admin?'../':''}index.html"><span class="brand-mark">✧</span> ASTRA</a><div class="brand-caption">${admin?'İDARƏETMƏ MƏRKƏZİ':'SƏNİN ŞƏXSİ KÖMƏKÇİN'}</div><nav class="nav" aria-label="Əsas naviqasiya">${items.map(id=>`<a href="${routes[id]}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${names[id]}</span></a>`).join('')}</nav><div class="side-footer"><div class="card" style="padding:16px;margin-bottom:24px"><small>✧ Səninlə, hər addımda.</small><p class="muted" style="font-size:10px;margin:10px 0 0">Daha aydın düşün. Daha rahat yaşa.</p></div><a class="text-btn" href="${admin?'../index.html':'admin/index.html'}">${admin?'← Tətbiqə qayıt':'İdarə paneli ↗'}</a><div class="profile"><span class="avatar">${esc(data.settings.name.slice(0,1)||'A')}</span><div>${esc(data.settings.name)}<br><small>Şəxsi hesab</small></div></div></div></aside><main class="main" id="main"><header class="topbar"><span class="breadcrumb">Şəxsi məkan &nbsp; / &nbsp; ${names[page]}</span><a class="mobile-brand" href="${admin?'../':''}index.html">✧ ASTRA</a><div class="row"><span><i class="status-dot"></i>Hesab bağlantısı</span>${ib('Yenilə','refresh','discover')}${ib('Bildirişlər','notifications','bell')}<a class="text-btn" href="${admin?'../':''}profile.html">Hesabım</a></div></header><div id="content"></div><footer class="bottom-note">ASTRA · Öz ritminlə yaşa. · Şəxsi hesab</footer></main></div>`;render();}
function jarvis(){if(data.features?.jarvis===false)return '';return `<section class="card jarvis"><div class="row between"><div class="row"><div class="orb"></div><div><h3 style="margin-bottom:7px">JARVIS</h3><span class="pill">${data.autopilot?'İCAZƏ AÇIQDIR':'AUTOPILOT DEAKTİVDİR'}</span></div></div>✧</div><p>${data.jobs.length?data.jobs.length+' hazırlıq işi var. Statuslara baxa bilərsən.':'Hazırlıq işi yoxdur. İcazə seçimlərini idarə edə bilərsən; İcazə verilmiş qeydlər üçün hazırlıq təklifləri yarada bilərsən.'}</p><div class="row between">${btn('Fəaliyyətlər','activity')}${btn('İdarə et','autopilot')}</div></section>`;}
function dateKey(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function localDateTime(iso){const d=new Date(iso);return dateKey(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');}
let selectedDay=dateKey(new Date());
function home(){const now=new Date(),start=new Date(now);start.setDate(now.getDate()-(now.getDay()+6)%7);const tasks=data.tasks.filter(t=>dateKey(new Date(t.dueAt))===selectedDay);const done=tasks.filter(t=>t.done).length,isToday=true;return heading(`Salam, ${esc(data.settings.name)} <span class="greeting-sun">${icon('sun')}</span>`,`${now.getDate()+' '+months[now.getMonth()]+' · '+weekdays[now.getDay()]} · Günün bir baxışda.`,btn('Yeni əlavə et','quick','primary','plus'))+`<div class="grid"><div class="stack"><section class="card"><div class="section-head"><h2>Günün ritmi</h2><small>${months[now.getMonth()]+' '+now.getFullYear()}</small></div><label style="margin-bottom:12px">Tarix<input type="date" id="plan-date" value="${selectedDay}" aria-label="Plan tarixi"></label><div class="week">${Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return `<button class="day ${dateKey(d)===selectedDay?'selected':''}" data-action="date:${dateKey(d)}" aria-pressed="${dateKey(d)===selectedDay}"><small>${['B.e.','Ç.a.','Ç.','C.a.','C.','Ş.','B.'][i]}</small><strong>${d.getDate()}</strong><small>${d.getDate()===now.getDate()?'•':'·'}</small></button>`;}).join('')}</div><div class="row between"><h3 style="margin:8px 0">${selectedDay===dateKey(now)?'Bu günün planı':esc(selectedDay)+' planı'}</h3><small>${isToday?done:0}/${isToday?tasks.length:0} tamamlandı</small></div><div class="progress-line"><span style="width:${isToday&&tasks.length?done/tasks.length*100:0}%"></span></div>${isToday?tasks.map(t=>`<div class="task ${t.done?'done':''}"><button class="check ${t.done?'checked':''}" aria-label="${esc(t.title)}" aria-pressed="${t.done}" data-action="task:${t.id}">${t.done?icon('check'):''}</button><span class="task-title">${esc(t.title)}</span><time>${esc(t.time)}</time>${ib('Redaktə et',`edit-task:${t.id}`,'edit')}${ib('Tapşırığı sil',`remove-task:${t.id}`,'close')}</div>`).join('')||'<p class="muted">İlk addımını əlavə et.</p>':'<p class="muted">Bu tarix üçün plan yoxdur.</p>'}<button class="add-line" data-action="new-task">＋ Tapşırıq əlavə et</button></section>${calendarCard()}${jarvis()}<section class="card"><div class="row"><span class="brand-mark">✧</span><div><h3>Kiçik bir xatırlatma</h3><p class="quote" style="margin:0">Hər şeyi bu gün bitirmək lazım deyil. Bir addım da irəliləyişdir.</p></div></div></section></div><div class="stack">${dailyMovieHTML(uiHelpers())}<section class="card"><div class="section-head"><h2>Fikirlərini itirmə</h2><a class="text-btn" href="notes.html">Hamısı →</a></div>${data.notes.slice(0,2).map(n=>`<button class="mini-note" style="width:100%;text-align:left" data-action="note:${n.id}"><h3>${esc(n.title)}</h3><p>${esc(n.body.slice(0,65))}…</p></button>`).join('')}<button class="add-line" data-action="new-note">＋ Sürətli qeyd yaz</button></section></div></div>`;}
const format=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>');
function noteResults(){return data.notes.filter(n=>(filter==='Hamısı'||n.category===filter)&&(n.title+' '+n.body).toLocaleLowerCase('az').includes(query.toLocaleLowerCase('az'))).sort((a,b)=>+b.pinned-+a.pinned||new Date(b.updated||0)-new Date(a.updated||0)).map(n=>`<article class="card note-card"><div class="row between"><span class="pill">${esc(n.category)}</span><button class="icon-btn" aria-label="Qeydi sabitlə" aria-pressed="${!!n.pinned}" style="color:${n.pinned?'var(--purple)':'var(--muted)'}" data-action="pin:${n.id}">${icon('pin')}</button></div><button style="text-align:left;padding:0" data-action="note:${n.id}"><h3>${esc(n.title)}</h3></button><div class="note-body formatted">${format(n.body.slice(0,180))}</div><footer><small>Şəxsi məkan</small><div class="row">${ib('JARVIS analizi',`analyze-note:${n.id}`,'ai')}${ib('Redaktə et',`note:${n.id}`,'edit')}${ib('Sil',`delete-note:${n.id}`,'trash')}</div></footer></article>`).join('')||'<div class="empty">Qeyd tapılmadı.<br><button class="text-btn" data-action="new-note">İlk qeydini yarat →</button></div>';}
function chips(values){return `<div class="chips" style="margin-bottom:24px">${values.map(v=>`<button class="chip ${v===filter?'active':''}" aria-pressed="${v===filter}" data-action="filter:${v}">${v}</button>`).join('')}</div>`;}
function notes(){return heading('Qeydlərin','Bir fikir, bir plan, bir gün. Hamısı burada.',btn('Yeni qeyd','new-note','primary','plus'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="search" type="search" aria-label="Qeydlərdə axtar" placeholder="Qeydlərində axtar…" value="${esc(query)}"></div></div>`+chips(['Hamısı','Şəxsi','Təhsil','İdeyalar','İş'])+`<div class="notes-grid" id="results">${noteResults()}</div>`;}
function discover(){return discoverHTML(uiHelpers());}
function ai(){return chatHTML(uiHelpers());}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function switches(){return ['autopilot','notesAccess'].map((key,i)=>`<div class="setting"><div><h3>${i?'Qeydlərə giriş icazəsi':'AutoPilot'}</h3><p>${i?'Hər qeyd üçün ayrıca analiz icazəsi də tələb olunur.':'İcazəli qeydlərin avtomatik AI analizinə və təsdiqlənmiş hazırlıq işlərinə icazə ver. Büdcən daxilində ödəniş yarana bilər.'}</p></div><button class="switch" role="switch" aria-label="${i?'Qeydlərə giriş':'AutoPilot'}" aria-checked="${data[key]}" data-action="toggle:${key}"></button></div>`).join('');}
function adminPage(){return renderAdmin(page,adminData,{heading,btn,ib,table,esc,movies});}
function render(){$('#content').innerHTML=admin?adminPage():page==='notes'&&data.features?.notes===false?heading('Qeydlər','Bu funksiya hazırda deaktivdir.'):({home,notes,discover,ai}[page])();if(page==='ai')bindChat(uiHelpers());if(page==='home'||page==='discover')bindMovies(uiHelpers());if(admin)bindAdmin(page,adminData,{toast,refresh:async args=>{try{adminArgs={...adminArgs,...args};adminData=await loadAdmin(page,adminArgs);adminData.offset=adminArgs.offset||0;render();toast('Dəyişiklik saxlanıldı.');}catch(error){toast(errorMessage(error));}}});$('#plan-date')?.addEventListener('change',e=>{if(e.target.value){selectedDay=e.target.value;render();}});$('#search')?.addEventListener('input',e=>{query=e.target.value;if(page==='notes')$('#results').innerHTML=noteResults();});$('#featured-form')?.addEventListener('submit',async e=>{e.preventDefault();await adminChange('featured_movie',new FormData(e.target).get('featured'));/* adminChange reports success */});$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name){toast('Ad daxil edin.');return;}data.settings.name=name;if(!await save())return;layout();toast('Parametrlər saxlanıldı.');});}
let previousFocus;function modal(title,body){if(!$('#modal').open)previousFocus=document.activeElement;$('#modal').innerHTML=`<div class="section-head"><h2>${title}</h2>${ib('Bağla','close','close')}</div>${body}`;if(!$('#modal').open)$('#modal').showModal();$('#modal').querySelector('input,textarea,select')?.focus();}
$('#modal').addEventListener('close',()=>previousFocus?.isConnected&&previousFocus.focus());
function confirm(title,callback){modal(title,`<p class="muted" style="margin-top:20px">Bu əməliyyat hesabınızdakı məlumatları dəyişəcək.</p><div class="form-actions">${btn('Ləğv et','close')}<button id="confirm" class="btn danger">Təsdiq et</button></div>`);$('#confirm').onclick=async()=>{await callback();$('#modal').close();};}
function noteEditor(id){const n=data.notes.find(n=>n.id===id)||{title:'',body:'',category:'Şəxsi',pinned:false};modal(id?'Qeydi redaktə et':'Yeni bir fikir',`<form id="note-form" class="form"><label>Başlıq<input name="title" maxlength="120" value="${esc(n.title)}" required></label><label>Kateqoriya<select name="category">${['Şəxsi','Təhsil','İdeyalar','İş'].map(c=>`<option ${n.category===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="row">${btn('Qalın','format:bold')}${btn('Maili','format:italic')}</div><label>Mətn<textarea name="body" id="note-body" maxlength="10000" required>${esc(n.body)}</textarea></label><label class="row"><input type="checkbox" name="analysis" ${n.analysisAllowed?'checked':''}>Bu qeydin AI provayderinə analiz üçün göndərilməsinə icazə verirəm</label><div class="form-actions">${btn('Ləğv et','close')}<button class="btn primary">Qeydi saxla</button></div></form>`);$('#note-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const f=new FormData(e.target),title=f.get('title').trim(),body=f.get('body').trim();if(!title||!body){toast('Başlıq və mətn boş ola bilməz.');return;}const record={...n,id:id||crypto.randomUUID(),title,body,category:f.get('category'),updated:new Date().toISOString()};if(id)data.notes=data.notes.map(x=>x.id===id?record:x);else data.notes.unshift(record);if(!await save())return;try{const client=await getClient();await rows(client.rpc('set_note_analysis',{note_id:record.id,allowed:f.has('analysis')}));data=await storage.load();}catch(error){toast(runtimeError(error));return;}$('#modal').close();render();toast('Qeyd saxlanıldı.');};}
function taskEditor(id){const task=data.tasks.find(t=>t.id===id);const date=task?dateKey(new Date(task.dueAt)):selectedDay;modal(task?'Tapşırığı redaktə et':'Yeni tapşırıq',`<form id="task-form" class="form"><label>Tapşırıq<input name="title" maxlength="160" value="${esc(task?.title||'')}" required></label><label>Təsvir<textarea name="description" maxlength="3000">${esc(task?.description||'')}</textarea></label><div class="row"><label>Tarix<input name="date" type="date" value="${date}" required></label><label>Vaxt<input name="time" type="time" value="${task?.time||'12:00'}" required></label></div><label>Prioritet<select name="priority">${[['low','Aşağı'],['normal','Normal'],['high','Yüksək']].map(([v,l])=>`<option value="${v}" ${task?.priority===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="btn primary">Saxla</button></form>`);$('#task-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const f=new FormData(e.target),title=f.get('title').trim();if(!title)return toast('Tapşırığın adını daxil edin.');const dueAt=new Date(f.get('date')+'T'+f.get('time')).toISOString();const record={id:id||crypto.randomUUID(),title,description:f.get('description').trim(),dueAt,time:f.get('time'),done:task?.done||false,priority:f.get('priority')};if(id)data.tasks=data.tasks.map(t=>t.id===id?record:t);else data.tasks.push(record);data.tasks.sort((a,b)=>a.dueAt.localeCompare(b.dueAt));selectedDay=f.get('date');if(!await save())return;$('#modal').close();render();toast('Tapşırıq saxlanıldı.');};}
function calendarCard(){if(data.features?.calendar===false)return '';return `<section class="card"><div class="section-head"><h2>Təqvim hadisələri</h2>${btn('Hadisə əlavə et','new-event','','plus')}</div>${data.events.filter(e=>dateKey(new Date(e.starts_at))===selectedDay).map(e=>`<div class="event-item"><div><h3>${esc(e.title)}</h3><p>${esc(new Date(e.starts_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))} — ${esc(new Date(e.ends_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))}</p><p>${esc(e.description)}</p></div><div class="row">${ib('Hadisəni redaktə et',`event:${e.id}`,'edit')}${ib('Hadisəni sil',`delete-event:${e.id}`,'trash')}</div></div>`).join('')||'<p class="muted">Bu tarix üçün hadisə yoxdur.</p>'}</section>`;}
function eventEditor(id){const event=data.events.find(e=>e.id===id);modal(event?'Hadisəni redaktə et':'Yeni təqvim hadisəsi',`<form id="event-form" class="form"><label>Başlıq<input name="title" maxlength="160" value="${esc(event?.title||'')}" required></label><label>Təsvir<textarea name="description" maxlength="3000">${esc(event?.description||'')}</textarea></label><label>Başlanğıc<input type="datetime-local" name="starts_at" value="${event?localDateTime(event.starts_at):selectedDay+'T12:00'}" required></label><label>Son<input type="datetime-local" name="ends_at" value="${event?localDateTime(event.ends_at):selectedDay+'T13:00'}" required></label><button class="btn primary">Saxla</button></form>`);$('#event-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const f=new FormData(e.target),title=f.get('title').trim(),starts_at=new Date(f.get('starts_at')).toISOString(),ends_at=new Date(f.get('ends_at')).toISOString();if(!title||ends_at<=starts_at)return toast('Başlıq və vaxt aralığını yoxlayın.');const record={id:id||crypto.randomUUID(),title,description:f.get('description').trim(),starts_at,ends_at};if(id)data.events=data.events.map(x=>x.id===id?record:x);else data.events.push(record);selectedDay=dateKey(new Date(starts_at));if(!await save())return;$('#modal').close();render();toast('Hadisə saxlanıldı.');};}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;if(saving)return;const [action,...parts]=el.dataset.action.split(':'),id=parts.join(':');switch(action){case 'close':$('#modal').close();break;case 'quick':modal('Nə əlavə edək?',`<div class="form">${btn('Yeni qeyd','new-note','','notes')}${btn('Yeni tapşırıq','new-task','','plus')}</div>`);break;case 'new-note':noteEditor();break;case 'note':noteEditor(id);break;case 'new-task':taskEditor();break;case 'edit-task':taskEditor(id);break;case 'new-event':eventEditor();break;case 'event':eventEditor(id);break;case 'delete-event':confirm('Hadisəni sil?',async()=>{data.events=data.events.filter(e=>e.id!==id);if(!await save())return;render();});break;case 'refresh':await refreshWorkspace();break;case 'date':selectedDay=id;render();break;case 'task':data.tasks=data.tasks.map(t=>t.id===id?{...t,done:!t.done}:t);if(!await save())return;render();break;case 'remove-task':confirm('Tapşırığı sil?',async()=>{data.tasks=data.tasks.filter(t=>t.id!==id);if(!await save())return;render();toast('Tapşırıq silindi.');});break;case 'pin':data.notes=data.notes.map(n=>n.id===id?{...n,pinned:!n.pinned}:n);if(!await save())return;render();break;case 'delete-note':confirm('Qeydi sil?',async()=>{data.notes=data.notes.filter(n=>n.id!==id);if(!await save())return;render();toast('Qeyd silindi.');});break;case 'format':{const t=$('#note-body'),m=id==='bold'?'**':'*';t.setRangeText(m+t.value.slice(t.selectionStart,t.selectionEnd)+m,t.selectionStart,t.selectionEnd,'select');t.focus();break;}case 'filter':filter=id;render();break;case 'notifications':await notificationCenter(uiHelpers());break;case 'autopilot':modal('JARVIS AutoPilot',switches()+'<p class="format-help" style="margin-top:20px">İcazəli qeydlər seçilən AI provayderinə ötürülə bilər. Büdcə və ödəniş razılığını hesabında idarə et.</p>'+btn('Fəaliyyət tarixçəsi','activity'));break;case 'toggle':data[id]=!data[id];if(!await save())return;el.setAttribute('aria-checked',data[id]);toast('Seçim saxlanıldı.');break;case 'activity':await activityCenter(uiHelpers());break;case 'analyze-note':await analyzeNote(id,uiHelpers());break;case 'notifications-toggle':data.settings.notifications=!data.settings.notifications;if(!await save())return;render();break;case 'reset':toast('Hesab məlumatlarını profildən idarə edin.');break;}});
async function start(){if(!configured){setupState();return;}try{const user=await requireSession();if(!user){location.replace(new URL('login.html',appRoot));return;}if(admin&&!await adminService.allowed()){deniedState();return;}data=await storage.load(user.id);sessionActive=true;if(!admin&&(page==='home'||page==='discover'))await initMovies();if(admin)adminData=await loadAdmin(page);layout();if(page==='ai')await initChat(uiHelpers(),user.id);document.querySelectorAll('.topbar .avatar').forEach(el=>{const a=document.createElement('a');a.className='avatar';a.href=new URL('profile.html',appRoot);a.textContent='H';a.setAttribute('aria-label','Hesabım');el.replaceWith(a);});await watchSession(user.id,()=>{sessionActive=false;storage.clear();data=storage.read();document.querySelector('#modal')?.close();document.querySelector('#app').replaceChildren();location.replace(new URL('login.html',appRoot));});}catch(error){failureState(error);}}
const appRoot=new URL('../../',import.meta.url);
function setupState(){$('#app').innerHTML='<main class="main"><section class="card"><h1>ASTRA</h1><h2>Supabase bağlantısı gözlənilir</h2><p class="muted">Şəxsi məlumatlar və admin panel bağlantı qurulana qədər açılmır. Konfiqurasiya üçün docs/SETUP.md təlimatını izləyin.</p><a class="btn primary" href="'+new URL('login.html',appRoot)+'">Giriş səhifəsi</a></section></main>';document.querySelector('.pet-widget')?.remove();}
function deniedState(){$('#app').innerHTML='<main class="main"><section class="card"><h1>Giriş məhduddur</h1><p>Bu səhifə üçün admin səlahiyyəti lazımdır.</p><a class="btn" href="'+new URL('index.html',appRoot)+'">Ana səhifəyə qayıt</a></section></main>';}
function failureState(error){$('#app').innerHTML='<main class="main"><section class="card"><h1>Bağlantı alınmadı</h1><p>'+esc(errorMessage(error))+'</p><button class="btn primary" id="retry">Yenidən yoxla</button><a class="btn" href="'+new URL('login.html',appRoot)+'">Giriş</a></section></main>';$('#retry').onclick=()=>start();}
async function adminChange(key,value){try{await adminService.call('setting',{key,value});adminData=await loadAdmin(page);render();toast('Dəyişiklik saxlanıldı.');}catch(error){toast(errorMessage(error));}}
start();if('serviceWorker'in navigator)navigator.serviceWorker.register(new URL('service-worker.js',appRoot)).catch(()=>{});

async function refreshWorkspace(){if(!sessionActive||saving||busy||$('#modal').open)return;try{const messages=data.messages;data=await storage.load();data.messages=messages;if(admin)adminData=await loadAdmin(page,adminArgs);render();}catch(error){if(accessFailure(error)){sessionActive=false;storage.clear();data=storage.read();failureState(error);}else toast(errorMessage(error));}}
window.addEventListener('focus',()=>{if(configured&&$('#content'))refreshWorkspace();});

function accessFailure(error){return error?.code==='42501'||error?.code==='PGRST301'||error?.status===401;}

function uiHelpers(){return {heading,btn,ib,icon,esc,modal,toast,data,render,userId:data.userId,addNote:async content=>{data.notes.unshift({id:crypto.randomUUID(),title:'AI cavabı',body:content.slice(0,10000),category:'İdeyalar',pinned:false});if(!await save())throw Error('SERVICE_ERROR');},toggle:async(kind,id)=>{const key={favorite:'favorites',watchlist:'watchlist',watched:'watched',disliked:'disliked'}[kind];data[key]=data[key].includes(id)?data[key].filter(v=>v!==id):[...data[key],id];if(!await save())throw Error('SERVICE_ERROR');toast('Film seçimi saxlanıldı.');render();}};}
